def solve():
    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        return
    t = int(data[0].strip())
    out_lines = []
    idx = 1
    for _ in range(t):
        if idx >= len(data):
            break
        line = data[idx].strip()
        idx += 1
        if not line:
            # skip empty
            continue
        parts = line.split()
        if len(parts) < 2:
            # maybe next line has second part
            if idx < len(data):
                parts.append(data[idx].strip())
                idx += 1
        if len(parts) < 2:
            # invalid
            continue
        a, b = parts[0], parts[1]
        # find common letters
        common = set(a) & set(b)
        if not common:
            out_lines.append("NO")
        else:
            # find first common letter in a
            chosen = None
            for ch in a:
                if ch in common:
                    chosen = ch
                    break
